    [11, 15, 5, 0, 1, 9, 8, 6, 14, 10, 2, 12, 3, 4, 7, 13],
];

// Flags
const CHUNK_START: u32 = 1 << 0;
const CHUNK_END: u32 = 1 << 1;
const PARENT: u32 = 1 << 2;
const ROOT: u32 = 1 << 3;
pub const KEYED_HASH: u32 = 1 << 4;
pub const DERIVE_KEY_CONTEXT: u32 = 1 << 5;
pub const DERIVE_KEY_MATERIAL: u32 = 1 << 6;

const BLOCK_LEN: usize = 64;
const CHUNK_LEN: usize = 1024;
const KEY_LEN: usize = 32;
const OUT_LEN: usize = 32;

#[inline(always)]
fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(x);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(y);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

fn round(state: &mut [u32; 16], msg: &[u32; 16], round_idx: usize) {
    let schedule = &MSG_SCHEDULE[round_idx];
    // Column step
    g(state, 0, 4, 8, 12, msg[schedule[0]], msg[schedule[1]]);
    g(state, 1, 5, 9, 13, msg[schedule[2]], msg[schedule[3]]);
    g(state, 2, 6, 10, 14, msg[schedule[4]], msg[schedule[5]]);
    g(state, 3, 7, 11, 15, msg[schedule[6]], msg[schedule[7]]);
    // Diagonal step
    g(state, 0, 5, 10, 15, msg[schedule[8]], msg[schedule[9]]);
    g(state, 1, 6, 11, 12, msg[schedule[10]], msg[schedule[11]]);
    g(state, 2, 7, 8, 13, msg[schedule[12]], msg[schedule[13]]);
    g(state, 3, 4, 9, 14, msg[schedule[14]], msg[schedule[15]]);
}

fn compress(
    chaining_value: &[u32; 8],
    block_words: &[u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 16] {
    let mut state = [
        chaining_value[0],
        chaining_value[1],
        chaining_value[2],
        chaining_value[3],
        chaining_value[4],
        chaining_value[5],
        chaining_value[6],
        chaining_value[7],
        IV[0],
        IV[1],
        IV[2],
        IV[3],
        counter as u32,
        (counter >> 32) as u32,
        block_len,
        flags,
    ];

    round(&mut state, block_words, 0);
    round(&mut state, block_words, 1);
    round(&mut state, block_words, 2);
    round(&mut state, block_words, 3);
    round(&mut state, block_words, 4);
    round(&mut state, block_words, 5);
    round(&mut state, block_words, 6);

    state[0] ^= state[8];
    state[1] ^= state[9];
    state[2] ^= state[10];
    state[3] ^= state[11];
    state[4] ^= state[12];
    state[5] ^= state[13];
    state[6] ^= state[14];
    state[7] ^= state[15];
    state[8] ^= chaining_value[0];
    state[9] ^= chaining_value[1];
    state[10] ^= chaining_value[2];
    state[11] ^= chaining_value[3];
    state[12] ^= chaining_value[4];
    state[13] ^= chaining_value[5];
    state[14] ^= chaining_value[6];
    state[15] ^= chaining_value[7];

    state
}

fn words_from_little_endian_bytes(bytes: &[u8]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..16 {
        let offset = i * 4;
        if offset + 4 <= bytes.len() {
            words[i] = u32::from_le_bytes([bytes[offset], bytes[offset+1], bytes[offset+2], bytes[offset+3]]);
        } else {
            // Pad with zeros (already 0)
            let mut tmp = [0u8; 4];
            let available = bytes.len() - offset;
            if available > 0 {
                tmp[..available].copy_from_slice(&bytes[offset..bytes.len()]);
            }
            words[i] = u32::from_le_bytes(tmp);
        }
    }
    words
}

fn first_8_words(compress_output: &[u32; 16]) -> [u32; 8] {
    [
        compress_output[0], compress_output[1], compress_output[2], compress_output[3],
        compress_output[4], compress_output[5], compress_output[6], compress_output[7],
    ]
}

struct ChunkState {
    chaining_value: [u32; 8],
    chunk_counter: u64,
    block: [u8; BLOCK_LEN],
    block_len: u8,
    blocks_compressed: u8,
    flags: u32,
}

impl ChunkState {
    fn new(key_words: &[u32; 8], chunk_counter: u64, flags: u32) -> Self {
        ChunkState {
            chaining_value: *key_words,
            chunk_counter,
            block: [0u8; BLOCK_LEN],
            block_len: 0,
            blocks_compressed: 0,
            flags,
        }
    }

    fn len(&self) -> usize {
        BLOCK_LEN * self.blocks_compressed as usize + self.block_len as usize
    }

    fn start_flag(&self) -> u32 {
        if self.blocks_compressed == 0 { CHUNK_START } else { 0 }
    }

    fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            // If we have a full block, compress it
            if self.block_len as usize == BLOCK_LEN {
                let block_words = words_from_little_endian_bytes(&self.block);
                self.chaining_value = first_8_words(&compress(
                    &self.chaining_value,
                    &block_words,
                    self.chunk_counter,
                    BLOCK_LEN as u32,
                    self.flags | self.start_flag(),
                ));
                self.blocks_compressed += 1;
                self.block = [0u8; BLOCK_LEN];
                self.block_len = 0;
            }

            let want = BLOCK_LEN - self.block_len as usize;
            let take = want.min(input.len());
            self.block[self.block_len as usize..self.block_len as usize + take]
                .copy_from_slice(&input[..take]);
            self.block_len += take as u8;
            input = &input[take..];
        }
    }

    fn output(&self) -> Output {
        let block_words = words_from_little_endian_bytes(&self.block);
        Output {
            input_chaining_value: self.chaining_value,
            block_words,
            counter: self.chunk_counter,
            block_len: self.block_len as u32,
            flags: self.flags | self.start_flag() | CHUNK_END,
        }
    }
}

struct Output {
    input_chaining_value: [u32; 8],
    block_words: [u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
}

impl Output {
    fn chaining_value(&self) -> [u32; 8] {
        first_8_words(&compress(
            &self.input_chaining_value,
            &self.block_words,
            self.counter,
            self.block_len,
            self.flags,
        ))
    }

    fn root_output_bytes(&self, out: &mut [u8]) {
        let mut output_block_counter = 0u64;
        let mut out_pos = 0;
        while out_pos < out.len() {
            let words = compress(
                &self.input_chaining_value,
                &self.block_words,
                output_block_counter,
                self.block_len,
                self.flags | ROOT,
            );
            // Write words as little-endian bytes
            let mut bytes = [0u8; 64];
            for (i, &word) in words.iter().enumerate() {
                let le = word.to_le_bytes();
                bytes[i * 4..(i+1)*4].copy_from_slice(&le);
            }
            let take = (out.len() - out_pos).min(64);
            out[out_pos..out_pos + take].copy_from_slice(&bytes[..take]);
            out_pos += take;
            output_block_counter += 1;
        }
    }
}

fn parent_output(
    left_child_cv: &[u32; 8],
    right_child_cv: &[u32; 8],
    key_words: &[u32; 8],
    flags: u32,
) -> Output {
    let mut block_words = [0u32; 16];
    block_words[..8].copy_from_slice(left_child_cv);
    block_words[8..].copy_from_slice(right_child_cv);
    Output {
        input_chaining_value: *key_words,
        block_words,
        counter: 0,
        block_len: BLOCK_LEN as u32,
        flags: flags | PARENT,
    }
}

fn parent_cv(
    left_child_cv: &[u32; 8],
    right_child_cv: &[u32; 8],
    key_words: &[u32; 8],
    flags: u32,
) -> [u32; 8] {
    parent_output(left_child_cv, right_child_cv, key_words, flags).chaining_value()
}

/// BLAKE3 hasher
pub struct Hasher {
    chunk_state: ChunkState,
    key_words: [u32; 8],
    cv_stack: Vec<[u32; 8]>,
    flags: u32,
}

impl Hasher {
    pub fn new() -> Self {
        Self::new_internal(&IV, 0)
    }

    pub fn new_keyed(key: &[u8; KEY_LEN]) -> Self {
        let key_words = key_words_from_bytes(key);
        Self::new_internal(&key_words, KEYED_HASH)
    }

    pub fn new_derive_key(context: &str) -> Self {
        let context_key = {
            let mut context_hasher = Self::new_internal(&IV, DERIVE_KEY_CONTEXT);
            context_hasher.update(context.as_bytes());
            context_hasher.finalize_bytes::<32>()
        };
        let context_key_words = key_words_from_bytes(&context_key);
        Self::new_internal(&context_key_words, DERIVE_KEY_MATERIAL)
    }

    fn new_internal(key_words: &[u32; 8], flags: u32) -> Self {
        Hasher {
            chunk_state: ChunkState::new(key_words, 0, flags),
            key_words: *key_words,
            cv_stack: Vec::new(),
            flags,
        }
    }

    fn add_chunk_chaining_value(&mut self, new_cv: [u32; 8], total_chunks: u64) {
        let mut total_chunks = total_chunks;
        let mut new_cv = new_cv;
        while total_chunks & 1 == 0 {
            let left = self.cv_stack.pop().unwrap();
            new_cv = parent_cv(&left, &new_cv, &self.key_words, self.flags);
            total_chunks >>= 1;
        }
        self.cv_stack.push(new_cv);
    }

    pub fn update(&mut self, mut input: &[u8]) -> &mut Self {
        while !input.is_empty() {
            // If chunk state is full, compress it and move to next chunk
            if self.chunk_state.len() == CHUNK_LEN {
                let chunk_cv = self.chunk_state.output().chaining_value();
                let total_chunks = self.chunk_state.chunk_counter + 1;
                self.add_chunk_chaining_value(chunk_cv, total_chunks);
                self.chunk_state = ChunkState::new(&self.key_words, total_chunks, self.flags);
            }

            let want = CHUNK_LEN - self.chunk_state.len();
            let take = want.min(input.len());
            self.chunk_state.update(&input[..take]);
            input = &input[take..];
        }
        self
    }

    fn finalize_output(&self) -> Output {
        // Start with the current chunk's output
        let mut output = self.chunk_state.output();

        // Merge with any parent nodes
        let mut parent_nodes_remaining = self.cv_stack.len();
        while parent_nodes_remaining > 0 {
            parent_nodes_remaining -= 1;
            output = parent_output(
                &self.cv_stack[parent_nodes_remaining],
                &output.chaining_value(),
                &self.key_words,
                self.flags,
            );
        }
        output
    }

    pub fn finalize(&self) -> [u8; OUT_LEN] {
        self.finalize_bytes::<OUT_LEN>()
    }

    pub fn finalize_bytes<const N: usize>(&self) -> [u8; N] {
        let mut out = [0u8; N];
        self.finalize_output().root_output_bytes(&mut out);
        out
    }

    pub fn finalize_xof(&self) -> OutputReader {
        OutputReader {
            inner: self.finalize_output(),
            position_within_block: 0,
            block_counter: 0,
            buf: [0u8; 64],
            buf_filled: false,
        }
    }
}

pub struct OutputReader {
    inner: Output,
    position_within_block: u8,
    block_counter: u64,
    buf: [u8; 64],
    buf_filled: bool,
}

impl OutputReader {
    fn fill_buf(&mut self) {
        let words = compress(
            &self.inner.input_chaining_value,
            &self.inner.block_words,
            self.block_counter,
            self.inner.block_len,
            self.inner.flags | ROOT,
        );
        for (i, &word) in words.iter().enumerate() {
            let le = word.to_le_bytes();
            self.buf[i * 4..(i+1)*4].copy_from_slice(&le);
        }
        self.buf_filled = true;
    }

    pub fn fill(&mut self, mut buf: &mut [u8]) {
        while !buf.is_empty() {
            if !self.buf_filled || self.position_within_block == 64 {
                if self.position_within_block == 64 {
                    self.block_counter += 1;
                    self.position_within_block = 0;
                }
                self.fill_buf();
            }
            let available = 64 - self.position_within_block as usize;
            let take = available.min(buf.len());
            buf[..take].copy_from_slice(&self.buf[self.position_within_block as usize..
                                                   self.position_within_block as usize + take]);
            self.position_within_block += take as u8;
            buf = &mut buf[take..];
        }
    }

    pub fn seek(&mut self, position: u64) {
        self.block_counter = position / 64;
        self.position_within_block = (position % 64) as u8;
        self.buf_filled = false;
    }
}

fn key_words_from_bytes(key: &[u8; 32]) -> [u32; 8] {
    let mut words = [0u32; 8];
    for i in 0..8 {
        words[i] = u32::from_le_bytes([key[i*4], key[i*4+1], key[i*4+2], key[i*4+3]]);
    }
    words
}

/// Hash bytes and return the 32-byte hash
pub fn hash(input: &[u8]) -> [u8; OUT_LEN] {
    let mut hasher = Hasher::new();
    hasher.update(input);
    hasher.finalize()
}

