fn parse_args() -> Result<Args, String> {
    let raw_args: Vec<String> = std::env::args().collect();
    let mut args = Args {
        keyed: false,
        derive_key: None,
        length: 32,
        seek: 0,
        num_threads: None,
        no_mmap: false,
        no_names: false,
        raw: false,
        tag: false,
        check: false,
        quiet: false,
        files: Vec::new(),
    };

    let mut i = 1;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        match arg.as_str() {
            "--help" => {
                print_usage(false);
                std::process::exit(0);
            }
            "-h" => {
                print_usage(true);
                std::process::exit(0);
            }
            "--version" | "-V" => {
                println!("b3sum {}", VERSION);
                std::process::exit(0);
            }
            "--keyed" => args.keyed = true,
            "--no-mmap" => args.no_mmap = true,
            "--no-names" => args.no_names = true,
            "--raw" => args.raw = true,
            "--tag" => args.tag = true,
            "--check" | "-c" => args.check = true,
            "--quiet" => args.quiet = true,
            "--derive-key" => {
                i += 1;
                if i >= raw_args.len() {
