            s if s.starts_with("--derive-key=") => {
                let val = &s["--derive-key=".len()..];
                args.derive_key = Some(val.to_string());
            }
            s if s.starts_with("--num-threads=") => {
                let val = &s["--num-threads=".len()..];
                match val.parse::<usize>() {
                    Ok(v) => args.num_threads = Some(v),
                    Err(_) => return Err(format!("invalid value for --num-threads: '{}'", val)),
