    reader.fill(&mut out);
    bytes_to_hex(&out)
}

fn get_hash_bytes(args: &Args, hasher: blake3::Hasher) -> Vec<u8> {
    let mut reader = hasher.finalize_xof();
    if args.seek > 0 {
        reader.seek(args.seek);
    }
    let mut out = vec![0u8; args.length];
    reader.fill(&mut out);
    out
}

fn hash_file(path: &str, args: &Args, key: Option<&[u8; 32]>) -> Result<String, String> {
    let mut hasher = create_hasher(args, key);
    if path == "-" {
        let stdin = io::stdin();
        let mut stdin_lock = stdin.lock();
        hash_reader(&mut stdin_lock, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    } else {
        let mut file = File::open(path)
            .map_err(|e| format!("{}: {}", path, e))?;
        hash_reader(&mut file, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    }
    Ok(get_hash_string(args, hasher))
}

fn hash_file_raw(path: &str, args: &Args, key: Option<&[u8; 32]>) -> Result<Vec<u8>, String> {
    let mut hasher = create_hasher(args, key);
    if path == "-" {
        let stdin = io::stdin();
        let mut stdin_lock = stdin.lock();
        hash_reader(&mut stdin_lock, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    } else {
        let mut file = File::open(path)
            .map_err(|e| format!("{}: {}", path, e))?;
        hash_reader(&mut file, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    }
    Ok(get_hash_bytes(args, hasher))
}

// Parse a checksum line, returning (hash, filename)
// Supports both:
//   HASH  FILENAME (standard format, with two spaces)
//   BLAKE3 (FILENAME) = HASH (BSD format)
fn parse_check_line(line: &str) -> Option<(String, String)> {
    let line = line.trim_end_matches('\n').trim_end_matches('\r');

    // Skip empty lines and comment lines
    if line.is_empty() || line.starts_with('#') {
        return None;
    }

    // Try BSD format: BLAKE3 (FILENAME) = HASH
    if line.starts_with("BLAKE3 (") {
        if let Some(end_paren) = line.find(") = ") {
            let filename = &line[8..end_paren];
            let hash = &line[end_paren + 4..];
            if !hash.is_empty() {
                return Some((hash.to_string(), filename.to_string()));
            }
        }
        return None;
    }

    // Standard format: HASH  FILENAME (two spaces)
    if let Some(pos) = line.find("  ") {
        let hash = &line[..pos];
        let filename = &line[pos + 2..];
        if !hash.is_empty() && !filename.is_empty() {
            return Some((hash.to_string(), filename.to_string()));
        }
    }

    None
}

fn run_check_mode(args: &Args, check_files: &[String]) -> bool {
    let mut any_failure = false;
    let mut had_error = false;

    for check_file in check_files {
        let lines: Vec<String> = if check_file == "-" {
            let stdin = io::stdin();
            stdin.lock().lines().map(|l| l.unwrap_or_default()).collect()
        } else {
            match std::fs::read_to_string(check_file) {
                Ok(content) => content.lines().map(|l| l.to_string()).collect(),
                Err(e) => {
                    eprintln!("b3sum: {}: {}", check_file, e);
                    had_error = true;
                    continue;
                }
            }
        };

        let mut failure_count = 0usize;

        for line in &lines {
            let line_trimmed = line.trim_end_matches('\n').trim_end_matches('\r');
            if line_trimmed.is_empty() || line_trimmed.starts_with('#') {
                continue;
            }

            match parse_check_line(line_trimmed) {
                None => {
                    // improperly formatted line - skip
                }
                Some((expected_hash, filename)) => {
                    // Derive length from hash length
                    let hash_len = expected_hash.len() / 2;
                    let check_args = Args {
                        keyed: false,
                        derive_key: None,
                        length: hash_len,
                        seek: 0,
                        num_threads: None,
                        no_mmap: false,
                        no_names: false,
                        raw: false,
                        tag: false,
                        check: false,
                        quiet: false,
                        files: vec![],
                    };
                    match hash_file(&filename, &check_args, None) {
                        Ok(actual_hash) => {
                            if actual_hash.to_lowercase() == expected_hash.to_lowercase() {
                                if !args.quiet {
                                    println!("{}: OK", filename);
                                }
                            } else {
                                println!("{}: FAILED", filename);
                                failure_count += 1;
                                any_failure = true;
                            }
                        }
                        Err(e) => {
                            eprintln!("b3sum: {}", e);
                            println!("{}: FAILED", filename);
                            failure_count += 1;
                            any_failure = true;
                        }
                    }
                }
            }
        }

        if failure_count > 0 {
            eprintln!("b3sum: WARNING: {} computed checksum{} did NOT match",
                failure_count,
                if failure_count == 1 { "" } else { "s" });
        }
    }

    !any_failure && !had_error
}

fn main() {
    let prog = get_prog_name();
    let args = match parse_args(&prog) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(2);
        }
    };

    // Validate argument combinations
    if args.keyed && args.derive_key.is_some() {
        eprintln!("error: the argument '--keyed' cannot be used with '--derive-key <CONTEXT>'");
        eprintln!();
        eprintln!("Usage: {} --keyed <FILE>...", prog);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if args.quiet && !args.check {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  --check");
        eprintln!();
        eprintln!("Usage: {} --check --quiet [FILE]...", prog);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if args.keyed && args.files.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <FILE>...");
        eprintln!();
        eprintln!("Usage: {} --keyed <FILE>...", prog);
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if args.raw && args.files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        std::process::exit(1);
    }

    // Check mode
    if args.check {
        let check_files = if args.files.is_empty() {
            vec!["-".to_string()]
        } else {
            args.files.clone()
        };
        let success = run_check_mode(&args, &check_files);
        if !success {
            std::process::exit(1);
        }
        return;
    }

    // Read key from stdin if keyed mode
    let key: Option<[u8; 32]> = if args.keyed {
        let stdin = io::stdin();
        let mut stdin_lock = stdin.lock();
        let mut key_buf = [0u8; 32];
        // Read exactly 32 bytes
        match stdin_lock.read_exact(&mut key_buf) {
            Ok(_) => {
                // Check there's no more data beyond 32 bytes
                let mut extra = [0u8; 1];
                match stdin_lock.read(&mut extra) {
                    Ok(0) => {} // EOF - good
                    Ok(_) => {
                        eprintln!("Error: read more than 32 key bytes from stdin");
                        std::process::exit(1);
                    }
                    Err(_) => {} // EOF or error - treat as OK
                }
                Some(key_buf)
            }
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let files = if args.files.is_empty() {
        vec!["-".to_string()]
    } else {
        args.files.clone()
    };

    // Check if keyed mode with stdin
    if args.keyed {
        for file in &files {
            if file == "-" {
                eprintln!("b3sum: {}: Cannot open `-` in keyed mode", file);
                std::process::exit(1);
            }
        }
    }

    // If --raw mode, output raw bytes
    if args.raw {
        // files should be exactly 1 (enforced above)
        match hash_file_raw(&files[0], &args, key.as_ref()) {
            Ok(bytes) => {
                let stdout = io::stdout();
                let mut stdout_lock = stdout.lock();
                if let Err(e) = stdout_lock.write_all(&bytes) {
                    eprintln!("b3sum: -: {}", e);
                    std::process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("b3sum: {}", e);
                std::process::exit(1);
            }
        }
        return;
    }

    let mut had_error = false;
    let stdout = io::stdout();
    let mut stdout_lock = stdout.lock();

    for file in &files {
        match hash_file(file, &args, key.as_ref()) {
            Ok(hash) => {
                if args.tag {
                    // BSD-style: BLAKE3 (FILENAME) = HASH
                    if let Err(e) = writeln!(stdout_lock, "BLAKE3 ({}) = {}", file, hash) {
                        eprintln!("b3sum: write error: {}", e);
                        std::process::exit(1);
                    }
                } else if args.no_names {
                    if let Err(e) = writeln!(stdout_lock, "{}", hash) {
                        eprintln!("b3sum: write error: {}", e);
                        std::process::exit(1);
                    }
                } else {
                    // Standard format: HASH  FILENAME (two spaces)
                    if let Err(e) = writeln!(stdout_lock, "{}  {}", hash, file) {
                        eprintln!("b3sum: write error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
            Err(e) => {
                eprintln!("b3sum: {}", e);
                had_error = true;
            }
        }
    }

    if had_error {
        std::process::exit(1);
    }
}
