fn hash_reader<R: Read>(
    reader: &mut R,
    hasher: &mut blake3::Hasher,
) -> io::Result<()> {
    let mut buf = vec![0u8; BLOCK_SIZE];
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(())
}

fn bytes_to_hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for &b in bytes {
        s.push_str(&format!("{:02x}", b));
    }
    s
}

fn create_hasher(args: &Args, key: Option<&[u8; 32]>) -> blake3::Hasher {
    if args.keyed {
        blake3::Hasher::new_keyed(key.unwrap())
    } else if let Some(ctx) = &args.derive_key {
        blake3::Hasher::new_derive_key(ctx)
    } else {
        blake3::Hasher::new()
    }
}

fn get_hash_string(args: &Args, hasher: blake3::Hasher) -> String {
    let mut reader = hasher.finalize_xof();
    if args.seek > 0 {
        reader.seek(args.seek);
    }
    let mut out = vec![0u8; args.length];
    reader.fill(&mut out);
    bytes_to_hex(&out)
}

fn get_hash_bytes(args: &Args, hasher: blake3::Hasher) -> Vec<u8> {
    let mut reader = hasher.finalize_xof();
    if args.seek > 0 {
        reader.seek(args.seek);
    }
    let mut out = vec![0u8; args.length];
    reader.fill(&mut out);
    out
}

fn hash_file(path: &str, args: &Args, key: Option<&[u8; 32]>) -> Result<String, String> {
    let mut hasher = create_hasher(args, key);
    if path == "-" {
        let stdin = io::stdin();
        let mut stdin_lock = stdin.lock();
        hash_reader(&mut stdin_lock, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    } else {
        let mut file = File::open(path)
            .map_err(|e| format!("{}: {}", path, e))?;
        hash_reader(&mut file, &mut hasher)
            .map_err(|e| format!("{}: {}", path, e))?;
    }
    Ok(get_hash_string(args, hasher))
}

fn hash_file_raw(path: &str, args: &Args, key: Option<&[u8; 32]>) -> Result<Vec<u8>, String> {
